{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { readFileSync } from 'node:fs'
import { parseSheet } from './sheet.js'
import { parseFormula, collectDeps } from './formula.js'
import { evaluateAll, formatValue } from './eval.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const parsed = parseSheet(readFileSync(0, 'utf8'))
if (parsed.error) {
  process.stderr.write(`error: ${parsed.error}\n`)
  process.exit(2)
}
const cells = parsed.cells // sorted array of {name, col, row, content}
for (const c of cells) {
  c.ast = c.content.startsWith('=') ? parseFormula(c.content.slice(1)) : null
}

let out = ''
if (args[0] === 'values') {
  const values = evaluateAll(cells)
  for (const c of cells) out += `${c.name}=${formatValue(values.get(c.name))}\n`
} else {
  for (const c of cells) {
    const deps = c.ast && c.ast.ok ? collectDeps(c.ast.node) : []
    out += `${c.name}:${deps.map((d) => ' ' + d).join('')}\n`
  }
}
process.stdout.write(out)
"}

