{"file_path":"src/sheet.js","content":"/** Address helpers and sheet-line parsing. */

export function parseAddress(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  const col = letters.length === 1
    ? letters.charCodeAt(0) - 64
    : 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
  return { col, row, name: letters + row }
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const seen = new Set()
  const cells = []
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue
    const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(line)
    const word = m[1]
    const a = parseAddress(word)
    if (!a) return { error: `line ${i + 1}: invalid cell address ${word}` }
    if (seen.has(a.name)) return { error: `line ${i + 1}: cell ${a.name} is declared twice` }
    seen.add(a.name)
    cells.push({ name: a.name, col: a.col, row: a.row, content: m[2] })
  }
  cells.sort((x, y) => x.col - y.col || x.row - y.row)
  return { cells }
}
"}

