import { parseAddress } from './sheet.js'
import { rangeCells, colName } from './formula.js'

const ERRORS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const err = (v) => ({ t: 'e', v })
const num = (v) => (Number.isFinite(v) ? { t: 'n', v } : err('#DIV/0!'))

export function formatValue(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function literal(content) {
  if (content === '') return { t: 'n', v: 0 }
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRORS.has(content)) return err(content)
  return { t: 's', v: content }
}

const rank = { n: 0, s: 1, b: 2 }
function cmpCodePoints(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 's') return cmpCodePoints(a.v, b.v)
  return Number(a.v) - Number(b.v)
}

/** Reads a value as a number; returns a number or an error value. */
function toNum(v) {
  if (v.t === 'n') return v.v
  if (v.t === 'b') return v.v ? 1 : 0
  return err('#VALUE!')
}

export function evaluateAll(cells) {
  const byName = new Map(cells.map((c) => [c.name, c]))
  const memo = new Map()
  const active = new Set()

  function cellValue(name) {
    if (memo.has(name)) return memo.get(name)
    const c = byName.get(name)
