    if (l.t === 'e') return l
    if (r.t === 'e') return r
    if (CMP_OPS[op]) return { t: 'b', v: CMP_OPS[op](compare(l, r)) }
    const a = toNum(l)
    if (typeof a !== 'number') return a
    const b = toNum(r)
    if (typeof b !== 'number') return b
