      if (cond.t === 'e') return cond
      let truth
      if (cond.t === 'b') truth = cond.v
      else if (cond.t === 'n') truth = cond.v !== 0
      else return err('#VALUE!')
      return ev(args[truth ? 1 : 2])
    }
    if (name === 'ABS') {
      const v = ev(args[0])
      if (v.t === 'e') return v
      const x = toNum(v)
      return typeof x === 'number' ? num(Math.abs(x)) : x
    }
    const vals = args.flatMap(argValues)
    const firstErr = vals.find((v) => v.t === 'e')
    if (firstErr) return firstErr
    if (name === 'COUNT') return { t: 'n', v: vals.filter((v) => v.t === 'n').length }
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (typeof x !== 'number') return x
      nums.push(x)
    }
